CREATE DATABASE IF NOT EXISTS invex_arquitectura CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE invex_arquitectura;

DROP TABLE IF EXISTS responsables;
DROP TABLE IF EXISTS lineamientos;
DROP TABLE IF EXISTS ciclo_vida_estatus;

CREATE TABLE ciclo_vida_estatus (id INT AUTO_INCREMENT PRIMARY KEY, etapa VARCHAR(50) NOT NULL, estatus VARCHAR(100) NOT NULL, activo TINYINT(1) NOT NULL DEFAULT 1, UNIQUE KEY uk_etapa_estatus (etapa, estatus)) ENGINE=InnoDB;

CREATE TABLE lineamientos (id INT AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(50) NOT NULL UNIQUE, dominio_ae VARCHAR(100) NOT NULL, grupo_id VARCHAR(100) NOT NULL, grupo_titulo VARCHAR(200) NOT NULL, declaracion TEXT NOT NULL, justificacion TEXT, implicaciones TEXT, ejemplo TEXT, excepcion TEXT, adoptado TINYINT(1) NOT NULL DEFAULT 0, etapa VARCHAR(50) NOT NULL DEFAULT 'Ideación', estatus_aplicable VARCHAR(100) NOT NULL DEFAULT 'Propuesto', fecha_declaracion DATE NULL, observacion TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_dominio (dominio_ae), INDEX idx_etapa (etapa), INDEX idx_estatus (estatus_aplicable)) ENGINE=InnoDB;

CREATE TABLE responsables (id INT AUTO_INCREMENT PRIMARY KEY, lineamiento_id INT NOT NULL, nombre VARCHAR(150) NOT NULL DEFAULT '', correo VARCHAR(255) NOT NULL DEFAULT '', orden INT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_responsable_lineamiento FOREIGN KEY (lineamiento_id) REFERENCES lineamientos(id) ON DELETE CASCADE, INDEX idx_responsable_lineamiento (lineamiento_id)) ENGINE=InnoDB;



-- Responsables iniciales: cada lineamiento comienza con un registro vacío para que el HTML pueda agregar tantos como se requiera.
