INSERT INTO ciclo_vida_estatus (etapa, estatus) VALUES
('Ideación', 'Propuesto'),
('Revisión de pares', 'En revisión'),
('Revisión de pares', 'Con observaciones'),
('Revisión de pares', 'Ajustado'),
('Revisión de pares', 'Conforme'),
('Aplicación', 'Pendiente de aprobación'),
('Aplicación', 'Aprobado'),
('Aplicación', 'Rechazado'),
('Aplicación', 'Devuelto para ajustes'),
('Publicación', 'Pendiente de publicación'),
('Publicación', 'Publicado'),
