INSERT INTO lineamientos (codigo, dominio_ae, grupo_id, grupo_titulo, declaracion, justificacion, implicaciones, ejemplo, excepcion, adoptado, etapa, estatus_aplicable, fecha_declaracion, observacion) VALUES
('LIN-ENT-001', '01_Arquitectura Empresarial', 'empresarial', 'Lineamientos de Arquitectura Empresarial', '"Toda iniciativa de negocio que requiera recursos tecnológicos deberá declarar y demostrar trazabilidad directa hacia al menos un Pilar Estratégico, un OKR corporativo o un mandato regulatorio."', 'Asegurar que las iniciativas tecnológicas respondan a las prioridades estratégicas de INVEX y que los recursos destinados a tecnología estén vinculados con objetivos de negocio, compromisos regulatorios o necesidades estratégicas claramente identificadas.', 'El Product Owner deberá documentar el alineamiento estratégico de la iniciativa mediante un Business Case o mecanismo equivalente. La iniciativa deberá identificar el Pilar Estratégico, OKR o mandato regulatorio relacionado antes de avanzar a las etapas formales de evaluación arquitectónica.', 'Una iniciativa para implementar un nuevo portal de referidos deberá demostrar su trazabilidad con un objetivo corporativo, por ejemplo, incrementar la captación digital durante un periodo determinado.', 'Podrán exceptuarse mandatos regulatorios de emergencia o acciones críticas de ciberseguridad y continuidad operativa que requieran atención inmediata, debiendo documentarse posteriormente su alineamiento y regularización.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-ENT-002', '01_Arquitectura Empresarial', 'empresarial', 'Lineamientos de Arquitectura Empresarial', '"El alcance de toda iniciativa deberá estructurarse identificando las Capacidades de Negocio del mapa empresarial de INVEX que serán impactadas, ya sea por creación, modificación o retiro."', 'Establecer un lenguaje común entre negocio y tecnología, facilitar la identificación de impactos, revelar posibles redundancias y promover la reutilización de capacidades y componentes corporativos.', 'La documentación arquitectónica de la iniciativa deberá incluir la identificación de las capacidades impactadas y su relación con el alcance funcional. El repositorio de arquitectura deberá registrar la relación entre iniciativa, capacidades de negocio y componentes afectados para facilitar el análisis de impacto y evolución.', 'Una iniciativa de nuevo onboarding deberá identificar las capacidades de negocio relacionadas, como Customer Offer, Party Authentication y Customer Agreement.', 'Podrán exceptuarse actualizaciones de infraestructura, redes o componentes técnicos que sean transparentes para el negocio y que no generen cambios en las capacidades o procesos empresariales.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-ENT-003', '01_Arquitectura Empresarial', 'empresarial', 'Lineamientos de Arquitectura Empresarial', '"Ninguna iniciativa deberá avanzar a Diseño Arquitectónico si el área usuaria no proporciona una definición funcional suficiente, incluyendo el entendimiento de los procesos As-Is y To-Be y los requerimientos funcionales correspondientes."', 'Asegurar que la necesidad de negocio esté claramente comprendida antes de definir soluciones tecnológicas, evitando trasladar a tecnología la responsabilidad de definir el problema, los procesos y el alcance funcional.', 'El área de negocio deberá proporcionar la información funcional necesaria para iniciar el análisis arquitectónico. La documentación deberá permitir identificar el proceso actual, el proceso objetivo, las necesidades funcionales, actores, principales reglas y alcance de la iniciativa.', 'Antes de solicitar una solución CRM, el área de Ventas deberá documentar el proceso actual de captación y el proceso objetivo, incluyendo los requerimientos funcionales que deberá atender la solución.', 'Podrán exceptuarse Pruebas de Concepto, MVPs o Spikes técnicos con duración limitada, cuyo objetivo sea validar viabilidad técnica o funcional antes de contar con una definición completa.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-ENT-004', '01_Arquitectura Empresarial', 'empresarial', 'Lineamientos de Arquitectura Empresarial', '"Desde la etapa de Ideación, el diseño conceptual de toda iniciativa deberá considerar y, cuando corresponda, ser validado formalmente por Riesgo Operacional, Cumplimiento Normativo y Seguridad de la Información."', 'Incorporar las consideraciones de riesgo, cumplimiento y seguridad desde las primeras etapas de la iniciativa, reduciendo impactos derivados de identificar restricciones regulatorias, de seguridad o de riesgo después de haber avanzado en el diseño.', 'Las iniciativas deberán identificar desde la etapa inicial los riesgos operativos, requerimientos regulatorios y consideraciones de seguridad aplicables. Las iniciativas que involucren información sensible, datos de clientes, operaciones financieras o servicios en nube deberán seguir los mecanismos de validación establecidos por las áreas correspondientes.', 'Una iniciativa que utilice Inteligencia Artificial Generativa para analizar perfiles de clientes deberá considerar desde la etapa conceptual los controles de protección de información y requerimientos de seguridad aplicables.', 'Podrán exceptuarse iniciativas internas de bajo impacto que no involucren datos de clientes, información sensible, operaciones financieras o procesos sujetos a requerimientos regulatorios específicos.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-ENT-005', '01_Arquitectura Empresarial', 'empresarial', 'Lineamientos de Arquitectura Empresarial', '"Las áreas de negocio no deberán seleccionar, preacordar ni iniciar procesos de contratación de software o servicios SaaS sin la validación previa de Arquitectura Empresarial."', 'Evitar la incorporación de soluciones tecnológicas no alineadas con la arquitectura corporativa, reducir duplicidades funcionales y tecnológicas, y prevenir riesgos relacionados con seguridad, integración, operación, información y costos de licenciamiento.', 'La adquisición de software o servicios SaaS deberá contar con la evaluación arquitectónica correspondiente antes de formalizar la contratación. Compras deberá considerar el dictamen o validación de Arquitectura Empresarial como parte de los requisitos aplicables al proceso de adquisición tecnológica.', 'Si Marketing requiere una nueva plataforma de automatización, deberá solicitar la evaluación de Arquitectura Empresarial antes de seleccionar o contratar el producto, considerando las capacidades existentes y las soluciones corporativas disponibles.', 'Podrán exceptuarse renovaciones de licenciamiento sin cambios relevantes en la arquitectura y contrataciones de servicios de consultoría o staffing que no impliquen la incorporación de una nueva solución tecnológica.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-SOL-001', '02_Arquitectura de Soluciones', 'soluciones', 'Lineamientos de Arquitectura de Soluciones', '"Toda operación deberá ubicarse primero en el mapa de capacidades de negocio y, a partir de dicha ubicación, determinar el Service Domain correspondiente. Si el Service Domain identificado no representa adecuadamente la capacidad, deberá corregirse la ubicación o registrarse una asignación propia con su sustento."', 'Asegurar que las decisiones de diseño de servicios partan de la necesidad de negocio y no exclusivamente de consideraciones tecnológicas, manteniendo además actualizado el mapa de capacidades y su relación con los Service Domains.', 'Cada iniciativa deberá documentar la capacidad de negocio en la que se ubica la operación, los Service Domains considerados, el Service Domain seleccionado y la justificación correspondiente. Cuando ningún Service Domain existente resulte adecuado, deberá documentarse la asignación propuesta y reportarse a Arquitectura Empresarial para su revisión e incorporación al mapa.', 'El onboarding de participantes se ubica en la capacidad Customer Management y se sirve mediante Party Lifecycle Management, descartando Trust Management debido a que este último administra el fideicomiso y no el alta de sus participantes.', 'Cuando una capacidad aún no esté cubierta por el mapa vigente, podrá registrarse una asignación propia debidamente sustentada, quedando sujeta a revisión por Arquitectura Empresarial.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-SOL-002', '02_Arquitectura de Soluciones', 'soluciones', 'Lineamientos de Arquitectura de Soluciones', '"Todo contrato de API nuevo o modificado deberá estar mapeado a un Service Domain del modelo BIAN v13.0, determinado y validado contra la referencia BIAN oficial."', 'Establecer una taxonomía común para los servicios y evitar que cada equipo defina clasificaciones independientes, facilitando la reutilización, interoperabilidad y trazabilidad de las capacidades de negocio hacia los servicios.', 'El arquitecto de la iniciativa deberá determinar y sustentar el Service Domain antes de definir el contrato de la API. La justificación deberá contrastarse con la definición oficial del Service Domain, considerando cuando corresponda su Service Role, Control Record y Behavior Qualifiers. Los Service Domains heredados de contratos existentes o propuestos por proveedores deberán ser revalidados.', 'El servicio de onboarding digital SOFID - Maat se mapea a Party Lifecycle Management y no a Fiduciary Agreement, debido a que administra el alta y documentación de participantes y no el cumplimiento del acuerdo fiduciario.', 'Podrán exceptuarse servicios técnicos o utilitarios de plataforma que no representen una capacidad de negocio, como health check, versionamiento, gestión de tokens de sesión o utilitarios de infraestructura.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-SOL-003', '02_Arquitectura de Soluciones', 'soluciones', 'Lineamientos de Arquitectura de Soluciones', '"La ruta de toda operación deberá seguir la estructura BIAN /{service-domain}/{behavior-qualifier}/{sub-qualifier}/{action-term}, incorporando los segmentos de Behavior Qualifier o Sub-Qualifier únicamente cuando la operación esté acotada a ellos."', 'Establecer una estructura de rutas predecible y consistente que permita identificar las operaciones del catálogo, facilitar su reutilización y soportar controles de duplicidad y evolución de los contratos.', 'Los segmentos deberán escribirse en minúscula y kebab-case, derivados de la nomenclatura BIAN. Las operaciones aplicables a todo el Control Record no deberán incorporar un segmento de Behavior Qualifier. El Sub-Qualifier deberá utilizarse únicamente para particionar una Behavior Qualifier existente.', 'POST /party-lifecycle-management/initiate para el registro de un participante y GET /party-lifecycle-management/documentation/retrieve para una consulta acotada a la Behavior Qualifier Documentation.', 'Las operaciones utilitarias sin identidad BIAN, como health check o versionamiento, podrán utilizar la convención técnica definida por la plataforma correspondiente.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-SOL-004', '02_Arquitectura de Soluciones', 'soluciones', 'Lineamientos de Arquitectura de Soluciones', '"Una operación de consulta deberá exponerse como GET, salvo que el request o response transporte un campo sensible, que el request contenga un array, un valor con caracteres + / = o más de tres campos no sensibles; en estos casos deberá utilizarse POST."', 'Evitar que información sensible sea expuesta mediante URLs y quede registrada en logs, historiales, proxies o cachés, así como prevenir problemas de serialización y representación de valores complejos en query strings.', 'Cada operación de lectura deberá documentar el criterio que determinó el verbo HTTP utilizado. La clasificación de sensibilidad de los campos deberá estar disponible antes de definir el contrato y deberá considerarse como insumo para la decisión.', 'Una consulta de expediente completo puede utilizar GET cuando únicamente requiere un identificador de negocio. Una consulta de movimientos de tarjeta deberá utilizar POST cuando transporte un identificador hasheado de tarjeta.', 'No habrá excepción cuando la operación contenga un campo sensible. Un dato sensible no deberá viajar en la URL aunque la operación sea exclusivamente de lectura.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-SOL-005', '02_Arquitectura de Soluciones', 'soluciones', 'Lineamientos de Arquitectura de Soluciones', '"Los mensajes no deberán contener objetos agrupadores de un solo uso y todo array deberá estar compuesto por objetos con campos nombrados, evitando arrays de tipos primitivos."', 'Facilitar la evolución de los contratos evitando estructuras innecesariamente profundas y reduciendo cambios incompatibles cuando sea necesario incorporar nuevos atributos a una colección.', 'Cuando se aplique una reestructuración respecto del contrato base deberá documentarse el cambio y comunicarse a los consumidores afectados. La estructura definida para un concepto deberá mantenerse consistente en los diferentes recursos del mismo contrato.', 'Un arreglo de roles que originalmente se recibía como una lista de textos deberá publicarse como una lista de objetos con un campo que represente el tipo de involucramiento, permitiendo incorporar posteriormente atributos como vigencia sin romper el contrato.', 'Podrán exceptuarse colecciones repetibles, el patrón {value, type} para identificadores y las agrupaciones que sean reutilizadas en varios mensajes del mismo contrato.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-APP-001', '03_Arquitectura de Aplicaciones', 'aplicaciones', 'Lineamientos de Arquitectura de Aplicaciones', '"Toda aplicación, sistema de aplicación, componente aplicativo, microservicio y servicio TI nuevo o modificado deberá estar registrado en el repositorio corporativo de arquitectura y mantener trazabilidad con los elementos de negocio y tecnológicos que justifican su existencia."', 'Evita arquitecturas aisladas, inventarios inconsistentes y componentes tecnológicos sin contexto. Permite conocer qué capacidades, procesos y funcionalidades soporta una aplicación y qué impacto genera modificarla.', 'Antes de aprobar una arquitectura de solución, los objetos afectados deberán existir o ser dados de alta en HOPEX y relacionarse, según corresponda, con capacidades, procesos, funcionalidades de negocio, sistemas de aplicaciones, aplicaciones, microservicios, servicios, información y deployment.', 'Un nuevo microservicio de CVV dinámico no queda documentado únicamente en un diagrama: se registra como objeto maestro y se relaciona con NOW Crédito, los servicios que expone, las funcionalidades que materializa y su deployment.', 'PoC o Spike técnico acotado que no llegue a producción. Deberá regularizarse si se decide industrializarlo.', 0, 'Ideación', 'Propuesto', '2026-09-17', ''),
('LIN-APP-002', '03_Arquitectura de Aplicaciones', 'aplicaciones', 'Lineamientos de Arquitectura de Aplicaciones', '"Toda solución deberá evaluar y reutilizar aplicaciones, componentes y servicios existentes antes de crear nuevos elementos aplicativos que cubran una capacidad o funcionalidad ya soportada."', 'Evita duplicidad funcional, proliferación innecesaria de componentes y crecimiento no controlado del portafolio aplicativo; favorece la reutilización y reducción del TCO.', 'El arquitecto deberá consultar el catálogo corporativo antes de proponer un nuevo Application, Micro-Service o IT Service. Si existe un elemento reutilizable deberá privileged su consumo; si no es viable, deberá documentarse la justificación para crear uno nuevo.', 'Una iniciativa requiere Consultar Promociones. Antes de desarrollar un servicio nuevo se verifica si existe una funcionalidad, IT Service o componente que ya la materializa y puede reutilizarse.', 'Cuando el componente existente no satisfaga requisitos demostrables de seguridad, capacidad, disponibilidad, aislamiento, regulación o evolución.', 0, 'Ideación', 'Propuesto', '2026-09-17', ''),
('LIN-APP-003', '03_Arquitectura de Aplicaciones', 'aplicaciones', 'Lineamientos de Arquitectura de Aplicaciones', '"Todo componente aplicativo o microservicio deberá tener una responsabilidad funcional claramente delimitada, alta cohesión y dependencias mínimas, evitando duplicar responsabilidades o incorporar lógica ajena a su dominio."', 'Reduce componentes con responsabilidades excesivas, duplicidad de lógica y dependencias que dificultan su evolución, mantenimiento y reutilización.', 'Cada microservicio deberá poder asociarse a funcionalidades concretas y declarar los servicios que expone y consume. Una nueva responsabilidad se incorporará al componente existente sólo cuando pertenezca al mismo contexto funcional.', 'Un microservicio responsable de CVV dinámico puede exponer Consultar CVV Dinámico, Consultar Estado, Enrolar y Cancelar si forman parte de una responsabilidad funcional coherente; no se crea necesariamente un microservicio por cada operación.', 'Componentes legacy o de terceros cuya partición no pueda modificarse. La excepción y, cuando corresponda, su estrategia de evolución deberán quedar documentadas.', 0, 'Ideación', 'Propuesto', '2026-09-17', ''),
('LIN-APP-004', '03_Arquitectura de Aplicaciones', 'aplicaciones', 'Lineamientos de Arquitectura de Aplicaciones', '"Toda interacción entre aplicaciones o componentes deberá declarar explícitamente el servicio, interfaz o contrato utilizado y la información intercambiada, evitando integraciones implícitas o dependencias no documentadas."', 'Permite analizar impacto, dependencias y reutilización, y evita que un flujo gráfico esconda qué servicio se consume y qué información circula entre los componentes.', 'Las arquitecturas deberán identificar proveedor, consumidor, IT Service o Application Service, interfaz/API cuando corresponda, Message Flow y Content intercambiado. Los contratos deberán relacionarse con los componentes que los exponen y consumen.', 'NOW consume el IT Service Consultar Promociones mediante una API/Interface; el Message Flow identifica la interacción y los Content Solicitud Consulta Promociones y Respuesta Consulta Promociones documentan la información intercambiada.', 'Interacciones puramente internas de implementación que no constituyan un contrato arquitectónicamente relevante.', 0, 'Ideación', 'Propuesto', '2026-09-17', ''),
('LIN-APP-005', '03_Arquitectura de Aplicaciones', 'aplicaciones', 'Lineamientos de Arquitectura de Aplicaciones', '"Todo sistema, aplicación y componente aplicativo deberá mantener un estado de ciclo de vida y responsable definidos, y toda incorporación, sustitución o retiro deberá evaluar su impacto sobre las dependencias registradas."', 'Evita aplicaciones huérfanas, componentes obsoletos sin control y retiros que afecten procesos, servicios, integraciones o consumidores dependientes.', 'Los elementos aplicativos deberán declarar al menos responsable, estado y ciclo de vida aplicable. Antes de retirar o sustituir un elemento se deberá consultar su impacto sobre procesos, funcionalidades, servicios, interfaces, información y tecnología relacionada.', 'Antes de retirar una aplicación legacy, HOPEX permite identificar qué procesos, IT Services, interfaces, consumidores y componentes dependen de ella para definir el plan de transición.', 'Componentes efímeros de laboratorio, sandbox o PoC que no soporten procesos productivos.', 0, 'Ideación', 'Propuesto', '2026-09-17', ''),
('LIN-DAT-001', '04_Arquitectura de Datos', 'datos', 'Lineamientos de Arquitectura de Datos', '"Toda solución deberá adoptar una arquitectura de datos alineada con los dominios empresariales definidos por INVEX, estableciendo claramente las responsabilidades, relaciones, fuentes y consumidores de la información."', 'Asegurar una visión integral y consistente de los datos, evitando duplicidades, silos de información y responsabilidades no definidas.', 'Las soluciones deberán identificar el dominio de datos correspondiente, sus responsables, relaciones, fuentes y principales consumidores.', 'Una nueva solución de crédito deberá identificar los dominios de Cliente, Producto, Crédito y Riesgo involucrados, así como sus fuentes y consumidores.', 'Podrán exceptuarse soluciones temporales o de contingencia debidamente justificadas y aprobadas por el mecanismo de gobierno establecido.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-DAT-002', '04_Arquitectura de Datos', 'datos', 'Lineamientos de Arquitectura de Datos', '"Todo dato crítico deberá contar con una definición empresarial, un responsable de negocio y una fuente de referencia claramente establecidos, evitando definiciones, propietarios o versiones no controladas."', 'Garantizar que los datos críticos tengan un significado común, responsabilidad definida y una referencia confiable para su uso dentro de INVEX.', 'Los datos críticos deberán contar con definición, responsable y fuente de referencia registrados y mantenidos durante su ciclo de vida.', 'El dato Cliente deberá contar con una definición empresarial común, un responsable de negocio y una fuente de referencia reconocida por INVEX.', 'Podrán utilizarse datos sin definición formal durante etapas exploratorias, siempre que se identifique su carácter temporal y se establezca un plan para su formalización.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-DAT-003', '04_Arquitectura de Datos', 'datos', 'Lineamientos de Arquitectura de Datos', '"Toda solución deberá garantizar la calidad, trazabilidad y protección de los datos de acuerdo con su criticidad, sensibilidad, ciclo de vida y propósito de negocio."', 'Reducir riesgos asociados al uso de información incorrecta, no trazable o expuesta de manera inadecuada, asegurando un uso confiable y controlado de los datos.', 'Deberán establecerse controles proporcionales a la criticidad y sensibilidad de la información, considerando calidad, trazabilidad, acceso, protección, conservación y disposición.', 'Para información financiera o de clientes, deberán existir controles de calidad, trazabilidad de origen y acceso conforme a su nivel de sensibilidad.', 'Podrán aplicarse controles diferenciados cuando la naturaleza, criticidad o propósito del dato no requiera el mismo nivel de control, previa justificación.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-DAT-004', '04_Arquitectura de Datos', 'datos', 'Lineamientos de Arquitectura de Datos', '"Toda integración o intercambio de datos deberá utilizar patrones, interfaces y contratos definidos, promoviendo la interoperabilidad, reutilización y evolución controlada de la información."', 'Evitar integraciones punto a punto no controladas y facilitar la interoperabilidad, reutilización y evolución de las soluciones de datos.', 'Las integraciones deberán definir interfaces, responsabilidades, formatos, reglas de intercambio y condiciones de evolución acordadas entre los participantes.', 'Una integración entre una aplicación de negocio y una plataforma de datos deberá utilizar una interfaz definida y un contrato que establezca la estructura y condiciones de intercambio.', 'Podrán utilizarse mecanismos alternativos en soluciones temporales, de contingencia o de baja criticidad, siempre que exista justificación y se defina su fecha o condición de regularización.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-DAT-005', '04_Arquitectura de Datos', 'datos', 'Lineamientos de Arquitectura de Datos', '"Toda decisión relevante de arquitectura de datos deberá ser evaluada y aprobada mediante el mecanismo de gobierno establecido, incluyendo su alineación arquitectónica, impacto, excepciones y evolución."', 'Asegurar que las decisiones relevantes de arquitectura sean consistentes con la estrategia, principios y lineamientos de INVEX.', 'Las decisiones deberán contar con la evaluación correspondiente, evidencia de aprobación, impactos identificados, excepciones autorizadas y condiciones para su evolución cuando aplique.', 'La incorporación de una nueva plataforma corporativa de datos deberá ser evaluada considerando su alineación con la arquitectura vigente, impactos, integraciones y evolución futura.', 'Las decisiones urgentes relacionadas con continuidad operativa podrán ejecutarse bajo mecanismos extraordinarios, debiendo ser regularizadas posteriormente conforme al proceso de gobierno.', 0, 'Ideación', 'Propuesto', NULL, ''),
('LIN-SEG-001', '05_Arquitectura de Seguridad', 'seguridad', 'Lineamientos de Arquitectura de Seguridad', '"Toda iniciativa deberá identificar los activos de negocio, información y tecnología que requieran protección, así como los riesgos asociados a su operación."', 'Permite establecer una visión integral de seguridad basada en los activos que generan valor para INVEX y los riesgos que pueden afectarlos.', 'La iniciativa deberá identificar activos críticos, propietarios, información involucrada, amenazas relevantes, impacto y nivel de protección requerido.', 'Una solución de Customer Master identifica información de clientes, identificadores, relaciones y APIs como activos sujetos a protección.', 'Podrán exceptuarse iniciativas exploratorias o PoC sin exposición a información productiva, siempre que se mantengan aisladas y controladas.', 0, 'Ideación', 'Propuesto', '2026-09-18', ''),
('LIN-SEG-002', '05_Arquitectura de Seguridad', 'seguridad', 'Lineamientos de Arquitectura de Seguridad', '"Todo activo de información deberá contar con clasificación de seguridad y controles de protección proporcionales a su sensibilidad, criticidad, uso y riesgo asociado."', 'Permite aplicar controles de seguridad de manera proporcional, evitando tanto la sobreprotección como la exposición innecesaria de información.', 'Los activos deberán clasificarse y relacionarse con controles de acceso, protección, monitoreo, conservación y disposición conforme al nivel determinado.', 'La información de identificación y contacto de clientes deberá clasificarse y contar con controles de acceso y protección acordes con su sensibilidad.', 'Podrán utilizarse controles temporales durante etapas de transición, siempre que exista análisis de riesgo y fecha definida para su regularización.', 0, 'Ideación', 'Propuesto', '2026-09-18', ''),
('LIN-SEG-003', '05_Arquitectura de Seguridad', 'seguridad', 'Lineamientos de Arquitectura de Seguridad', '"Toda solución deberá implementar seguridad desde su diseño, incorporando controles de identidad, acceso, protección, trazabilidad y monitoreo conforme a los riesgos identificados."', 'Integra la seguridad desde las primeras decisiones arquitectónicas y reduce la necesidad de incorporar controles de manera reactiva durante la implementación.', 'Los diseños deberán documentar los controles de seguridad requeridos y su relación con los activos, riesgos, procesos y componentes tecnológicos involucrados.', 'Una API de consulta de clientes deberá considerar autenticación, autorización, protección de información, trazabilidad de accesos y monitoreo.', 'Podrán exceptuarse prototipos técnicos aislados que no procesen información productiva ni se conecten con servicios corporativos.', 0, 'Ideación', 'Propuesto', '2026-09-18', ''),
('LIN-SEG-004', '05_Arquitectura de Seguridad', 'seguridad', 'Lineamientos de Arquitectura de Seguridad', '"Toda interacción con información o servicios críticos deberá ser atribuible a una identidad autorizada y contar con mecanismos de trazabilidad suficientes para su supervisión."', 'Permite conocer quién accede, modifica o utiliza información y servicios críticos, facilitando la detección de eventos y la atención de incidentes.', 'Las soluciones deberán implementar mecanismos de identificación, autenticación, autorización y registro de eventos conforme a la criticidad del servicio o información.', 'Las modificaciones realizadas sobre información maestra de clientes deberán asociarse a una identidad autorizada y conservar evidencia de la operación.', 'Podrán existir procesos técnicos automatizados sin identidad individual, siempre que utilicen identidades de servicio controladas y auditables.', 0, 'Ideación', 'Propuesto', '2026-09-18', ''),
('LIN-SEG-005', '05_Arquitectura de Seguridad', 'seguridad', 'Lineamientos de Arquitectura de Seguridad', '"Toda decisión de arquitectura que modifique el nivel de exposición o riesgo de un activo crítico deberá contar con evaluación, responsable y evidencia de aceptación o tratamiento del riesgo."', 'Asegura que los cambios relevantes de arquitectura sean evaluados de forma explícita y que los riesgos residuales tengan un responsable definido.', 'Las decisiones deberán documentar activos afectados, riesgo identificado, controles existentes, tratamiento propuesto, responsable y vigencia de la aceptación cuando aplique.', 'La exposición de una API de Customer Master hacia un canal externo deberá evaluar los riesgos y controles antes de su habilitación.', 'En situaciones de continuidad operativa, podrán aplicarse controles extraordinarios, debiendo documentarse el riesgo y regularizarse posteriormente.', 0, 'Ideación', 'Propuesto', '2026-09-18', '');
INSERT INTO responsables (lineamiento_id, nombre, correo, orden) SELECT id, '', '', 1 FROM lineamientos;
